const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('website_museum_zai-glm-5.3_01.html', 'utf8');

// 1. Syntax-check every inline <script> block (catches console-breaking JS errors)
const scripts = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map(m => m[1]).filter(s => s.trim());
let jsOk = true;
scripts.forEach((s, i) => {
  try { new vm.Script(s); console.log(`script[${i}] OK (${s.length} chars)`); }
  catch (e) { jsOk = false; console.log(`script[${i}] SYNTAX ERROR: ${e.message}`); }
});

// 2. Cross-reference nav anchor hrefs with actual section ids
const ids = new Set([...html.matchAll(/id="([^"]+)"/g)].map(m => m[1]));
const hrefs = [...html.matchAll(/href="#([^"]+)"/g)].map(m => m[1]);
const missing = [...new Set(hrefs)].filter(h => !ids.has(h) && h !== '');
console.log('anchor targets:', [...new Set(hrefs)].join(', '));
console.log('missing anchor targets:', missing.length ? missing.join(', ') : 'none');

console.log(jsOk && missing.length === 0 ? 'ALL CHECKS PASSED' : 'CHECKS FAILED');

